-- PostgreSQL review DDL. Deploy through SQLAlchemy models and Alembic.
-- Connect to database devdb before executing this script.
-- IDs and SHA-256 hashes are generated by the application.
BEGIN;

CREATE SCHEMA IF NOT EXISTS crosstax;

CREATE TABLE crosstax.rule_sources (
    id VARCHAR(36) PRIMARY KEY,
    name VARCHAR(200) NOT NULL,
    jurisdiction_code VARCHAR(2) NOT NULL,
    url TEXT NOT NULL UNIQUE,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    etag TEXT,
    last_modified TEXT,
    last_checked_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (length(jurisdiction_code) = 2)
);

CREATE TABLE crosstax.rule_sync_runs (
    id VARCHAR(36) PRIMARY KEY,
    trigger_type VARCHAR(20) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'RUNNING',
    started_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    finished_at TIMESTAMP WITH TIME ZONE,
    error_message TEXT,
    summary JSON NOT NULL,
    CHECK (trigger_type IN ('SCHEDULED', 'MANUAL')),
    CHECK (status IN ('RUNNING', 'SUCCEEDED', 'PARTIAL', 'FAILED')),
    CHECK ((status = 'RUNNING' AND finished_at IS NULL)
        OR (status <> 'RUNNING' AND finished_at IS NOT NULL)),
    CHECK (finished_at IS NULL OR finished_at >= started_at)
);
CREATE INDEX ix_rule_sync_runs_started ON crosstax.rule_sync_runs (started_at);

CREATE TABLE crosstax.rule_documents (
    id VARCHAR(36) PRIMARY KEY,
    source_id VARCHAR(36) NOT NULL REFERENCES crosstax.rule_sources(id) ON DELETE RESTRICT,
    sync_run_id VARCHAR(36) NOT NULL REFERENCES crosstax.rule_sync_runs(id) ON DELETE RESTRICT,
    content_hash VARCHAR(64) NOT NULL CHECK (length(content_hash) = 64),
    content_type VARCHAR(100) NOT NULL,
    raw_content BYTEA NOT NULL,
    extracted_text TEXT,
    fetched_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (source_id, content_hash)
);
CREATE INDEX ix_rule_documents_sync_run ON crosstax.rule_documents (sync_run_id);
CREATE INDEX ix_rule_documents_source_fetched ON crosstax.rule_documents (source_id, fetched_at);

CREATE TABLE crosstax.rule_versions (
    version_id VARCHAR(64) PRIMARY KEY CHECK (length(version_id) = 64),
    schema_version INTEGER NOT NULL DEFAULT 1 CHECK (schema_version > 0),
    rules JSON NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'CANDIDATE',
    validation_report JSON NOT NULL,
    extraction_metadata JSON NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    approved_at TIMESTAMP WITH TIME ZONE,
    CHECK (status IN ('CANDIDATE', 'APPROVED', 'REJECTED')),
    CHECK ((status = 'APPROVED' AND approved_at IS NOT NULL)
        OR (status <> 'APPROVED' AND approved_at IS NULL))
);
CREATE INDEX ix_rule_versions_status_created ON crosstax.rule_versions (status, created_at);

-- A complete ruleset can reference multiple source documents.
CREATE TABLE crosstax.rule_version_documents (
    version_id VARCHAR(64) NOT NULL REFERENCES crosstax.rule_versions(version_id) ON DELETE RESTRICT,
    document_id VARCHAR(36) NOT NULL REFERENCES crosstax.rule_documents(id) ON DELETE RESTRICT,
    PRIMARY KEY (version_id, document_id)
);
CREATE INDEX ix_rule_version_documents_document ON crosstax.rule_version_documents (document_id);

-- One permanent row. Application reads revision and uses optimistic CAS on publish.
CREATE TABLE crosstax.rule_engine_state (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    active_version_id VARCHAR(64) REFERENCES crosstax.rule_versions(version_id) ON DELETE RESTRICT,
    revision INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0),
    activated_at TIMESTAMP WITH TIME ZONE,
    CHECK ((active_version_id IS NULL AND activated_at IS NULL)
        OR (active_version_id IS NOT NULL AND activated_at IS NOT NULL))
);
INSERT INTO crosstax.rule_engine_state (id) VALUES (1);

COMMIT;
